CustomFunction.Calculation:
// Recursively extracts JSON property key names from a ¶-delimited list of
// SQL column expressions (already in SQL form, e.g. "Table"."Field").
// Delegates single-expression extraction to QueryParseSelectKey.
// Call with index = 1.
Let
(
[
_expr = Trim ( GetValue ( colList ; index ) ) ;
_key = QueryParseSelectKey ( _expr ) ;
_rest = If ( index < itemCount ;
	"¶" & QueryParseSelectKeysSQL ( colList ; itemCount ; index + 1 ) ;
	""
	)
] ;
_key & _rest
)
